"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timedelta

_DIGITS = re.compile(r"[0-9]+")
_MONTH_NAMES = {name: i for i, name in enumerate("JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split(), start=1)}
_DOW_NAMES = {name: i for i, name in enumerate("SUN MON TUE WED THU FRI SAT".split())}

# (low, high, names) for minute, hour, day-of-month, month, day-of-week
_FIELDS = (
    (0, 59, {}),
    (0, 23, {}),
    (1, 31, {}),
    (1, 12, _MONTH_NAMES),
    (0, 7, _DOW_NAMES),
)


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


@dataclass(frozen=True)
class _Spec:
    minutes: frozenset[int]
    hours: frozenset[int]
    days: frozenset[int]
    months: frozenset[int]
    weekdays: frozenset[int]
    dom_restricted: bool
    dow_restricted: bool


def _value(text: str, low: int, high: int, names: dict[str, int]) -> int:
    if _DIGITS.fullmatch(text):
        number = int(text)
    elif text.upper() in names:
        number = names[text.upper()]
    else:
        raise CronError(f"malformed value {text!r}")
    if not low <= number <= high:
        raise CronError(f"value {number} outside {low}-{high}")
    return number


def _parse_term(term: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    body, slash, step_text = term.partition("/")
    step = 1
    if slash:
        if not _DIGITS.fullmatch(step_text):
            raise CronError(f"malformed step {step_text!r}")
        step = int(step_text)
        if step < 1:
            raise CronError(f"step must be at least 1, got {step}")

    if body == "*":
        first, last = low, high
    else:
        left, dash, right = body.partition("-")
        first = _value(left, low, high, names)
        if dash:
            last = _value(right, low, high, names)
            if first > last:
                raise CronError(f"range {body!r} has its low bound above its high bound")
        elif slash:
            last = high
        else:
            last = first
    return set(range(first, last + 1, step))


def _parse_field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    values: set[int] = set()
    for term in text.split(","):
        values |= _parse_term(term, low, high, names)
    return values


def _parse(expr: str) -> _Spec:
    fields = expr.split()
    if len(fields) != 5:
        raise CronError(f"expected 5 fields, got {len(fields)}: {expr!r}")
    minutes, hours, days, months, weekdays = (
        _parse_field(text, low, high, names) for text, (low, high, names) in zip(fields, _FIELDS)
    )
    return _Spec(
        minutes=frozenset(minutes),
        hours=frozenset(hours),
        days=frozenset(days),
        months=frozenset(months),
        weekdays=frozenset(day % 7 for day in weekdays),
        # Only the exact text "*" is unrestricted; "*/1" restricts the field.
        dom_restricted=fields[2] != "*",
        dow_restricted=fields[4] != "*",
    )


def _day_matches(t: datetime, spec: _Spec) -> bool:
    dom_ok = t.day in spec.days
    dow_ok = (t.weekday() + 1) % 7 in spec.weekdays
    if spec.dom_restricted and spec.dow_restricted:
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def _horizon(start: datetime) -> datetime:
    try:
        return start.replace(year=start.year + 5)
    except ValueError:  # February 29
        return start.replace(year=start.year + 5, day=28)


def _next_match(t: datetime, spec: _Spec, limit: datetime) -> datetime:
    while t <= limit:
        if t.month not in spec.months:
            t = datetime(t.year + (t.month == 12), t.month % 12 + 1, 1)
        elif not _day_matches(t, spec):
            t = t.replace(hour=0, minute=0) + timedelta(days=1)
        elif t.hour not in spec.hours:
            t = t.replace(minute=0) + timedelta(hours=1)
        elif t.minute not in spec.minutes:
            t += timedelta(minutes=1)
        else:
            return t
    raise CronError("no firing within five years of start")


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    spec = _parse(expr)
    limit = _horizon(start)
    firings: list[datetime] = []
    t = start.replace(second=0, microsecond=0) + timedelta(minutes=1)
    while len(firings) < count:
        t = _next_match(t, spec, limit)
        firings.append(t)
        t += timedelta(minutes=1)
    return firings
